import{_ as a,o as t,c as r,a3 as i}from"./chunks/framework.D3oaa6bG.js";const u=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{"title":"Getting Started","editLink":true},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":null}'),l={name:"guide/index.md"};function n(o,e,s,p,h,d){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="mall-winter-cms-plugin" tabindex="-1">Mall Winter CMS Plugin <a class="header-anchor" href="#mall-winter-cms-plugin" aria-label="Permalink to &quot;Mall Winter CMS Plugin&quot;">​</a></h1><p>Welcome to the official documentation of the <strong>Mall</strong> plugin, the all-inclusive e-commerce solution for the Laravel-based WinterCMS.</p><p>On the following pages you will find all the information you need to install the plugin on your website and integrate it in your used theme. You will also read about the individual models, controllers and how you can extend them to integrate your own functions.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If you think, that some details are missing or not sufficiently well explained, we invite you to extend and add this to our documentation. For this case you will find an &quot;Edit this page on GitHub&quot; link at the bottom of each page, which brings you to the corresponding markdown file in our Github repository. Thanks for your help!</p></div><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>We highly recommend using the latest WinterCMS v3 and PHP v8 versions available, however, the following requirements represent the minimum needed to run Mall on your website.</p><ul><li>WinterCMS v1.2+ | v1.3+</li><li>PHP v8.1+</li><li>MySQL v5.7+ | v8.0+ <strong><code>or</code></strong> MariaDB v10.2+ <strong><code>or</code></strong> SQLite<span style="color:red;"><strong>*</strong></span> v3.19+</li></ul><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p><span style="color:red;"><strong>*</strong></span> Although it is possible to use Mall via SQLite, we strongly recommend using one of the other database systems, especially on a large number of products or customers.</p></div><h3 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h3><p>Mall relies on the following official WinterCMS Plugins, which must be installed before installing the Mall extension itself.</p><ul><li><a href="https://github.com/wintercms/wn-user-plugin" target="_blank" rel="noreferrer">Winter.User</a> v2.3+</li><li><a href="https://github.com/wintercms/wn-location-plugin" target="_blank" rel="noreferrer">Winter.Location</a> v2.2+</li><li><a href="https://github.com/wintercms/wn-translate-plugin" target="_blank" rel="noreferrer">Winter.Translate</a> v2.3+</li></ul><p>Mall also requires the following PHP packages, which should be installed automatically, when installing Mall via <code>composer</code> on WinterCMS v1.2+ installations.</p><ul><li><a href="https://packagist.org/packages/barryvdh/laravel-dompdf" target="_blank" rel="noreferrer">barryvdh/laravel-dompdf</a> v2.1+ | v3.1+</li><li><a href="https://packagist.org/packages/hashids/hashids" target="_blank" rel="noreferrer">hashids/hashids</a> v4.1+</li><li><a href="https://packagist.org/packages/league/omnipay" target="_blank" rel="noreferrer">league/omnipay</a> v3.2+</li><li><a href="https://packagist.org/packages/omnipay/paypal" target="_blank" rel="noreferrer">omnipay/paypal</a> v3.0+</li><li><a href="https://packagist.org/packages/omnipay/stripe" target="_blank" rel="noreferrer">omnipay/stripe</a> v3.0+</li></ul><h3 id="optional-dependencies" tabindex="-1">Optional dependencies <a class="header-anchor" href="#optional-dependencies" aria-label="Permalink to &quot;Optional dependencies&quot;">​</a></h3><p>The following dependencies are only required if necessary, but must be installed manually if needed.</p><ul><li><a href="https://packagist.org/packages/bummzack/omnipay-postfinance" target="_blank" rel="noreferrer">bummzack/omnipay-postfinance</a> - To use the PostFinance payment provider</li><li><a href="https://packagist.org/packages/offline/jsonq" target="_blank" rel="noreferrer">offline/jsonq</a> - To use the file based index</li><li><a href="https://packagist.org/packages/tmarois/filebase" target="_blank" rel="noreferrer">tmarois/filebase</a> - To use the file based index</li><li><a href="https://packagist.org/packages/vitalybaev/google-merchant-feed" target="_blank" rel="noreferrer">vitalybaev/google-merchant-feed</a> - To use the Google Merchant Feed integration</li><li><a href="https://github.com/stripe/stripe-php" target="_blank" rel="noreferrer">stripe/stripe-php</a> - To use the Stripe Hosted Checkout payment provider</li></ul><h3 id="development-dependencies" tabindex="-1">Development dependencies <a class="header-anchor" href="#development-dependencies" aria-label="Permalink to &quot;Development dependencies&quot;">​</a></h3><p>The following dependencies are only required when developing or extending the Mall plugin itself, and must be installed manually as well, of course.</p><ul><li><a href="https://packagist.org/packages/fakerphp/faker" target="_blank" rel="noreferrer">fakerphp/faker</a> v1.23+</li><li><a href="https://packagist.org/packages/mockery/mockery" target="_blank" rel="noreferrer">mockery/mockery</a> v1.6+</li><li><a href="https://packagist.org/packages/omnipay/stripe" target="_blank" rel="noreferrer">phpunit/phpunit</a> v8.5+ | v9.0+</li><li><a href="https://packagist.org/packages/squizlabs/php_codesniffer" target="_blank" rel="noreferrer">squizlabs/php_codesniffer</a> v3.0+</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://mall.offline.swiss" target="_blank" rel="noreferrer">Demo Website</a></li><li>Mall Plugin - <a href="https://github.com/wintercms/wn-mall-plugin" target="_blank" rel="noreferrer">GitHub</a></li><li>Demo Theme - <a href="https://github.com/wintercms/wn-mall-theme" target="_blank" rel="noreferrer">GitHub</a></li></ul>',21)])])}const g=a(l,[["render",n]]);export{u as __pageData,g as default};
